const chats=[{n:"Ammi",m:"Beta khana kha liya?",t:"10:30 AM",num:"+92 300 1234567",about:"Meri Ammi - Duaon Mein Yaad Rakhna",isGroup:false},{n:"Bhai",m:"Kal aa raha hoon",t:"9:00 AM",num:"+92 321 7654321",about:"Bhai",isGroup:false},{n:"Ayesha",m:"Hi",t:"Yesterday",num:"+92 333 9876543",about:"Hey There! I am using Speeko",isGroup:false},{n:"My Moti",m:"I love you",t:"9:15 AM",num:"+92 300 5555555",about:"Meri Jaan",isGroup:false},{n:"Family Group",m:"Sab kahan ho?",t:"Yesterday",num:"Group - 5 Members",about:"Family Group - Sab Family Yahan Hai",isGroup:true},{n:"Friends Group",m:"Kal match hai",t:"Yesterday",num:"Group - 8 Members",about:"Friends Group",isGroup:true}];
