const emojis:any={Face:["😀","😁","😂","🤣","😊","😍","😘","😎","😢","😭","😡","😴","🤔","😇","🥰","😜","🤩","😷","🤯","😱","🥳","😈","👻","💀"],Hand:["👍","👎","🙏","👏","✌️","🤞","👌","👋","🤝","💪","🖐️","✋","👊","🤲","🙌"],Love:["❤️","🧡","💛","💚","💙","💜","🖤","🤍","💔","💕","💖","💘","💯","✨","⭐","🔥","🎉","🎊","🎈","🎁","🌹"]};
